                       output wire [63 : 0] sum_2,
                       output wire [63 : 0] sum_3                                                                     
                      );


  //----------------------------------------------------------------
  // Parameters and symbolic values.
  //----------------------------------------------------------------
  localparam CTRL_IDLE     = 5'h0;
  localparam CTRL_OP1      = 5'h1;
  localparam CTRL_OP2      = 5'h2;
  localparam CTRL_OP3      = 5'h3;
  localparam CTRL_OP4      = 5'h4;
  localparam CTRL_SUM_0    = 5'h5;
  localparam CTRL_OP5      = 5'h6;
  localparam CTRL_OP6      = 5'h7;
  localparam CTRL_OP7      = 5'h8;
  localparam CTRL_OP8      = 5'h9;
  localparam CTRL_OP9      = 5'ha;
  localparam CTRL_SUM_1    = 5'hb;
  localparam CTRL_OP10     = 5'hc;
  localparam CTRL_OP11     = 5'hd;
  localparam CTRL_OP12     = 5'he;
  localparam CTRL_OP13     = 5'hf;
  localparam CTRL_OP14     = 5'h10;  
  localparam CTRL_SUM_2    = 5'h11;
  localparam CTRL_OP15     = 5'h12;
  localparam CTRL_OP16     = 5'h13;
  localparam CTRL_OP17     = 5'h14;  
  localparam CTRL_OP18     = 5'h15;  
  localparam CTRL_OP19     = 5'h16;   
  localparam CTRL_SUM_3    = 5'h17;

  //----------------------------------------------------------------
  // Registers including update variables and write enable.
  //----------------------------------------------------------------
  reg [63 : 0] mul_reg;
  reg [63 : 0] mul_new;
  reg          mul_we;

  reg [63 : 0] sum_0_reg;
  reg [63 : 0] sum_1_reg;
  reg [63 : 0] sum_2_reg;
  reg [63 : 0] sum_3_reg;
  reg [63 : 0] sum_new;
  reg          sum_we;

  reg          ready_reg;
  reg          ready_new;
  reg          ready_we;

  reg [4 : 0]  mulacc_ctrl_reg;
  reg [4 : 0]  mulacc_ctrl_new;
  reg          mulacc_ctrl_we;


  //----------------------------------------------------------------
  // wires
  //----------------------------------------------------------------
  reg [4 : 0]  mulop_select;
  reg          update_mul;
  reg          clear_sum;
  reg          update_sum;

  //----------------------------------------------------------------
  // counter control
  //----------------------------------------------------------------

  reg [1 : 0]  control_operator;

  //----------------------------------------------------------------
  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  assign sum_0   = sum_0_reg;
  assign sum_1   = sum_1_reg;
  assign sum_2   = sum_2_reg;
  assign sum_3   = sum_3_reg;
  assign ready = ready_reg;


  //----------------------------------------------------------------
  // reg_update
  //
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with synchronous
  // active low reset.
  //----------------------------------------------------------------
  always @ (posedge clk)
    begin : reg_update
      if (!reset_n)
        begin
          mul_reg         <= 64'h0;
          sum_0_reg       <= 64'h0;
          sum_1_reg       <= 64'h0;
          sum_2_reg       <= 64'h0;
          sum_3_reg       <= 64'h0;
          ready_reg       <= 1'h0;
          mulacc_ctrl_reg <= CTRL_IDLE;
        end
      else
        begin
          if (mul_we)
            mul_reg <= mul_new;

          if (sum_we)
          
            case (control_operator)
                0:
                begin
                    sum_0_reg <= sum_new;
                end

                1:
                begin
                    sum_1_reg <= sum_new;
                end

                2:
                begin
                    sum_2_reg <= sum_new;
                end

                3:
                begin
                    sum_3_reg <= sum_new;
                end
        
                default:
                begin
                end
            endcase // case (control_operator) 
            

          if (ready_we)   
            ready_reg <= ready_new;

          if (mulacc_ctrl_we)
            mulacc_ctrl_reg <= mulacc_ctrl_new;
        end
    end // reg_update


  //----------------------------------------------------------------
  // mulacc_logic
  //----------------------------------------------------------------
  always @*
    begin : mulacc_logic
      reg [31 : 0] mul_opa;
      reg [63 : 0] mul_opb;

      mul_opa = 32'h0;
      mul_opb = 64'h0;
      mul_new = 64'h0;
      mul_we  = 1'h0;
      sum_new = 64'h0;
      sum_we  = 1'h0;


      case (mulop_select)
        0:
          begin
            mul_opa = opa0_0;
            mul_opb = opb0;
          end

        1:
          begin
            mul_opa = opa1_0;
            mul_opb = opb1;
          end

        2:
          begin
            mul_opa = opa2_0;
            mul_opb = opb2;
          end

        3:
          begin
            mul_opa = opa3_0;
            mul_opb = opb3;
          end

        4:
          begin
            mul_opa = opa4_0;
            mul_opb = opb4;
          end

        5:
          begin
            mul_opa = opa0_1;
            mul_opb = opb0;
          end
 
         6:
          begin
            mul_opa = opa1_1;
            mul_opb = opb1;
          end
          
         7:
          begin
            mul_opa = opa2_1;
            mul_opb = opb2;
          end

        8:
          begin
            mul_opa = opa3_1;
            mul_opb = opb3;
          end
          
        9:
          begin
            mul_opa = opa4_1;
            mul_opb = opb4;
          end          
 
         10:
          begin
            mul_opa = opa0_2;
            mul_opb = opb0;
          end
 
         11:
          begin
            mul_opa = opa1_2;
            mul_opb = opb1;
          end
 
         12:
          begin
            mul_opa = opa2_2;
            mul_opb = opb2;
          end
 
         13:
          begin
            mul_opa = opa3_2;
            mul_opb = opb3;
          end

        14:
          begin
            mul_opa = opa4_2;
            mul_opb = opb4;
          end

        15:
          begin
            mul_opa = opa0_3;
            mul_opb = opb0;
          end

        16:
          begin
            mul_opa = opa1_3;
            mul_opb = opb1;
          end

        17:
          begin
            mul_opa = opa2_3;
            mul_opb = opb2;
          end

        18:
          begin
            mul_opa = opa3_3;
            mul_opb = opb3;
          end

        19:
          begin
            mul_opa = opa4_3;
            mul_opb = opb4;
          end


        default:
          begin
          end
      endcase // case (mulop_select)


      if (update_mul)
        begin
          mul_new = mul_opa * mul_opb;
          mul_we  = 1'h1;
        end

      if (clear_sum)
        begin
          sum_new = 64'h0;
          sum_we  = 1;
        end

      if (update_sum)
        begin
        
        case (control_operator)
            0:
            begin
                sum_new = sum_0_reg + mul_reg;
                sum_we  = 1;
            end

          1:
             begin
               sum_new = sum_1_reg + mul_reg;
               sum_we  = 1;
             end

           2:
             begin
                sum_new = sum_2_reg + mul_reg;
                sum_we  = 1;
              end

           3:
             begin
               sum_new = sum_3_reg + mul_reg;
               sum_we  = 1;
          end
        
            default:
             begin
             end
         endcase // case (control_operator) 

        end
    end


  //----------------------------------------------------------------
  // mulacc_ctrl
  //----------------------------------------------------------------
  always @*
    begin : mulacc_ctrl
      mulop_select    = 5'h0;
      update_mul      = 1'h0;
      clear_sum       = 1'h0;
      update_sum      = 1'h0;
      ready_new       = 1'h0;
      ready_we        = 1'h0;
      mulacc_ctrl_new = CTRL_IDLE;
      mulacc_ctrl_we  = 1'h0;
      control_operator= 2'h0;

      case (mulacc_ctrl_reg)
        CTRL_IDLE:
          begin
            if (start)
              begin
                mulop_select    = 5'h0;
                ready_new       = 1'h0;
                ready_we        = 1'h1;
                update_mul      = 1'h1;
                clear_sum       = 1'h1;
                mulacc_ctrl_new = CTRL_OP1;
                mulacc_ctrl_we  = 1'h1;
                control_operator= 2'h0;
              end
          end

        CTRL_OP1:
          begin
            mulop_select    = 5'h1;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP2;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h0;
          end

        CTRL_OP2:
          begin
            mulop_select    = 5'h2;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP3;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h0;
          end

        CTRL_OP3:
          begin
            mulop_select    = 5'h3;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP4;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h0;
          end

        CTRL_OP4:
          begin
            mulop_select    = 5'h4;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_SUM_0;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h0;
          end

        CTRL_SUM_0:
          begin
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP5;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h0;            
          end
          
        CTRL_OP5:
          begin
            mulop_select    = 5'h5;
            update_mul      = 1'h1;
            update_sum      = 1'h0;           
            clear_sum       = 1'h1;
            mulacc_ctrl_new = CTRL_OP6;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h1;
          end

        CTRL_OP6:
          begin
            mulop_select    = 5'h6;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP7;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h1;
          end

        CTRL_OP7:
          begin
            mulop_select    = 5'h7;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP8;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h1;
          end
          
         CTRL_OP8:
          begin
            mulop_select    = 5'h8;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP9;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h1;
          end
          
        CTRL_OP9:
          begin
            mulop_select    = 5'h9;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_SUM_1;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h1;
          end

        CTRL_SUM_1:
          begin
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP10;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h1;            
          end

        CTRL_OP10:
          begin
            mulop_select    = 5'ha;
            update_mul      = 1'h1;
            update_sum      = 1'h0;           
            clear_sum       = 1'h1;
            mulacc_ctrl_new = CTRL_OP11;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h2;
          end

        CTRL_OP11:
          begin
            mulop_select    = 5'hb;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP12;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h2;
          end

        CTRL_OP12:
          begin
            mulop_select    = 5'hc;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP13;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h2;
          end
          
         CTRL_OP13:
          begin
            mulop_select    = 5'hd;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP14;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h2;
          end
          
        CTRL_OP14:
          begin
            mulop_select    = 5'he;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_SUM_2;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h2;
          end

        CTRL_SUM_2:
          begin
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP15;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h2;            
          end
          
        CTRL_OP15:
          begin
            mulop_select    = 5'hf;
            update_mul      = 1'h1;
            update_sum      = 1'h0;           
            clear_sum       = 1'h1;
            mulacc_ctrl_new = CTRL_OP16;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h3;
          end

        CTRL_OP16:
          begin
            mulop_select    = 5'h10;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP17;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h3;
          end

        CTRL_OP17:
          begin
            mulop_select    = 5'h11;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP18;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h3;
          end
          
         CTRL_OP18:
          begin
            mulop_select    = 5'h12;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_OP19;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h3;
          end
          
        CTRL_OP19:
          begin
            mulop_select    = 5'h13;
            update_mul      = 1'h1;
            update_sum      = 1'h1;
            mulacc_ctrl_new = CTRL_SUM_3;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h3;
          end  

        CTRL_SUM_3:
          begin
            update_sum      = 1'h1;
            ready_new       = 1'h1;
            ready_we        = 1'h1;
            mulacc_ctrl_new = CTRL_IDLE;
            mulacc_ctrl_we  = 1'h1;
            control_operator= 2'h3;            
          end

        default:
          begin
          end
      endcase // case (mulacc_ctrl_reg)
    end

endmodule // poly1305_mulacc

