module poly1305_core(
                     input wire            clk,
                     input wire            reset_n,

                     input wire            init,
                     input wire            next,
                     input wire            finish,

                     output wire           ready,

                     input wire [255 : 0]  key,

                     input wire [127 : 0]  block,
                     input wire [4 : 0]    blocklen,

                     output wire [127 : 0] mac
                    );


  //----------------------------------------------------------------
  // Internal constant and parameter definitions.
  //----------------------------------------------------------------
  localparam CTRL_IDLE      = 3'h0;
  localparam CTRL_INIT      = 3'h1;
  localparam CTRL_NEXT      = 3'h2;
  localparam CTRL_NEXT_WAIT = 3'h3;
  localparam CTRL_FINAL     = 3'h4;
  localparam CTRL_READY     = 3'h7;


  //----------------------------------------------------------------
  // Internal functions.
  //----------------------------------------------------------------
  function [31 : 0] le(input [31 : 0] w);
    le = {w[7 : 0], w[15 : 8], w[23 : 16], w[31 : 24]};
  endfunction // le


  //----------------------------------------------------------------
  // Registers including update variables and write enable.
  //----------------------------------------------------------------
  reg  [31 : 0] h_reg [0 : 4];
  reg  [31 : 0] h_new [0 : 4];
  reg           h_we;

  reg [31 : 0]  c_reg [0 : 4];
  reg [31 : 0]  c_new [0 : 4];
  reg           c_we;

  reg [31 : 0]  r_reg [0 : 3];
  reg [31 : 0]  r_new [0 : 3];
  reg           r_we;

  reg [31 : 0]  s_reg [0 : 3];
  reg [31 : 0]  s_new [0 : 3];
  reg           s_we;

  reg [31 : 0]  mac_reg [0 : 3];
  reg [31 : 0]  mac_new [0 : 3];
  reg           mac_we;

  reg           ready_reg;
  reg           ready_new;
  reg           ready_we;

  reg [2 : 0]   poly1305_core_ctrl_reg;
  reg [2 : 0]   poly1305_core_ctrl_new;
  reg           poly1305_core_ctrl_we;


  //----------------------------------------------------------------
  // Wires.
  //----------------------------------------------------------------
  reg  pblock_start;
  wire pblock_ready;

  reg  final_start;
  wire final_ready;

  reg state_init;
  reg state_update;
  reg load_block;
  reg mac_update;

  wire [31 : 0] hres0;
  wire [31 : 0] hres1;
  wire [31 : 0] hres2;
  wire [31 : 0] hres3;

  wire [31 : 0] pblock_h_new [0 : 4];


  //----------------------------------------------------------------
  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  assign mac[031 : 000] = mac_reg[0];
  assign mac[063 : 032] = mac_reg[1];
  assign mac[095 : 064] = mac_reg[2];
  assign mac[127 : 096] = mac_reg[3];

  assign ready = ready_reg;


  //----------------------------------------------------------------
  // Module instantiations.
  //----------------------------------------------------------------
  poly1305_pblock pblock_inst(
                              .clk(clk),
                              .reset_n(reset_n),

                              .start(pblock_start),
                              .ready(pblock_ready),

                              .h0(h_reg[0]),
                              .h1(h_reg[1]),
                              .h2(h_reg[2]),
                              .h3(h_reg[3]),
                              .h4(h_reg[4]),

                              .c0(c_reg[0]),
                              .c1(c_reg[1]),
                              .c2(c_reg[2]),
                              .c3(c_reg[3]),
                              .c4(c_reg[4]),

                              .r0(r_reg[0]),
                              .r1(r_reg[1]),
                              .r2(r_reg[2]),
                              .r3(r_reg[3]),

                              .h0_new(pblock_h_new[0]),
                              .h1_new(pblock_h_new[1]),
                              .h2_new(pblock_h_new[2]),
                              .h3_new(pblock_h_new[3]),
                              .h4_new(pblock_h_new[4])
                             );

  poly1305_final final_inst(
                            .clk(clk),
                            .reset_n(reset_n),

                            .start(final_start),
                            .ready(final_ready),

                            .h0(h_reg[0]),
                            .h1(h_reg[1]),
                            .h2(h_reg[2]),
                            .h3(h_reg[3]),
                            .h4(h_reg[4]),

                            .s0(s_reg[0]),
                            .s1(s_reg[1]),
                            .s2(s_reg[2]),
                            .s3(s_reg[3]),

                            .hres0(hres0),
                            .hres1(hres1),
                            .hres2(hres2),
                            .hres3(hres3)
                           );


  //----------------------------------------------------------------
  // reg_update
  //
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with synchronous
  // active low reset.
  //----------------------------------------------------------------
  always @ (posedge clk)
    begin : reg_update
      integer i;
      if (!reset_n)
        begin
          for (i = 0 ; i < 5 ; i = i + 1)
            begin
              h_reg[i] <= 32'h0;
              c_reg[i] <= 32'h0;
            end

          for (i = 0 ; i < 4 ; i = i + 1)
            begin
              r_reg[i]   <= 32'h0;
              s_reg[i]   <= 32'h0;
              mac_reg[i] <= 32'h0;
            end

          ready_reg              <= 1'h1;
          poly1305_core_ctrl_reg <= CTRL_IDLE;
        end
      else
        begin
          if (ready_we)
            ready_reg <= ready_new;

          if (h_we)
            begin
              for (i = 0 ; i < 5 ; i = i + 1)
                h_reg[i] <= h_new[i];
            end

          if (c_we)
            begin
              for (i = 0 ; i < 5 ; i = i + 1)
                c_reg[i] <= c_new[i];
            end

          if (r_we)
            begin
              for (i = 0 ; i < 4 ; i = i + 1)
                r_reg[i] <= r_new[i];
            end

          if (s_we)
            begin
              for (i = 0 ; i < 4 ; i = i + 1)
                s_reg[i] <= s_new[i];
            end

          if (mac_we)
            begin
              for (i = 0 ; i < 4 ; i = i + 1)
                mac_reg[i] <= mac_new[i];
            end

          if (poly1305_core_ctrl_we)
            poly1305_core_ctrl_reg <= poly1305_core_ctrl_new;
        end
    end // reg_update


  //----------------------------------------------------------------
  // poly1305_core_logic
  //----------------------------------------------------------------
  always @*
    begin : poly1305_core_logic
      integer i;
      reg [31 : 0] b0;
      reg [31 : 0] b1;
      reg [31 : 0] b2;
      reg [31 : 0] b3;

      for (i = 0 ; i < 5 ; i = i + 1)
        h_new[i] = 32'h0;
      h_we = 1'h0;

      for (i = 0 ; i < 5 ; i = i + 1)
        c_new[i] = 32'h0;
      c_we = 1'h0;

      for (i = 0 ; i < 4 ; i = i + 1)
        r_new[i] = 32'h0;
      r_we = 1'h0;

      for (i = 0 ; i < 4 ; i = i + 1)
        s_new[i] = 32'h0;
      s_we = 1'h0;

      for (i = 0 ; i < 4 ; i = i + 1)
        mac_new[i] = 32'h0;
      mac_we = 1'h0;

      b0 = le(block[031 : 000]);
      b1 = le(block[063 : 032]);
      b2 = le(block[095 : 064]);
      b3 = le(block[127 : 096]);

      if (state_init)
        begin
          c_we     = 1'h1;
          h_we     = 1'h1;

          // Clamping of the key when assigning r.
          r_new[0] = le(key[255 : 224]) & 32'h0fffffff;
          r_new[1] = le(key[223 : 192]) & 32'h0ffffffc;
          r_new[2] = le(key[191 : 160]) & 32'h0ffffffc;
          r_new[3] = le(key[159 : 128]) & 32'h0ffffffc;
          r_we     = 1'h1;

          s_new[0] = le(key[127 : 096]);
          s_new[1] = le(key[095 : 064]);
          s_new[2] = le(key[063 : 032]);
          s_new[3] = le(key[031 : 000]);
          s_we     = 1'h1;
        end

      // Note that we only check bits 0..3 in blocklen.
      // This means that a blocklen of 0 and 16 are
      // handled the same way.
      if (load_block)
        begin
          if (blocklen[3 : 0] > 0)
            begin
              // Handling of partial (final) blocks.
              case (blocklen[3 : 0])
                0: begin
                  c_new[0] = 32'h1;
                end

                1: begin
                  c_new[0] = {24'h1, b3[7 : 0]};
                end

                2: begin
                  c_new[0] = {16'h1, b3[15 : 0]};
                end

                3: begin
                  c_new[0] = {8'h1, b3[23 : 0]};
                end

                4: begin
                  c_new[0] = b3;
                  c_new[1] = 32'h1;
                end

                5: begin
                  c_new[0] = b3;
                  c_new[1] = {24'h1, b2[7 : 0]};
                end

                6: begin
                  c_new[0] = b3;
                  c_new[1] = {16'h1, b2[15 : 0]};
                end

                7: begin
                  c_new[0] = b3;
                  c_new[1] = {8'h1, b2[23 : 0]};
                end

                8: begin
                  c_new[0] = b3;
                  c_new[1] = b2;
                  c_new[2] = 32'h1;
                end

                9: begin
                  c_new[0] = b3;
                  c_new[1] = b2;
                  c_new[2] = {24'h1, b1[7 : 0]};
                end

                10: begin
                  c_new[0] = b3;
                  c_new[1] = b2;
                  c_new[2] = {16'h1, b1[15 : 0]};
                end

                11: begin
                  c_new[0] = b3;
                  c_new[1] = b2;
                  c_new[2] = {8'h1, b1[23 : 0]};
                end

                12: begin
                  c_new[0] = b3;
                  c_new[1] = b2;
                  c_new[2] = b1;
                  c_new[3] = 32'h1;
                end

                13: begin
                  c_new[0] = b3;
                  c_new[1] = b2;
                  c_new[2] = b1;
                  c_new[3] = {24'h1, b0[7 : 0]};
                end

                14: begin
                  c_new[0] = b3;
                  c_new[1] = b2;
                  c_new[2] = b1;
                  c_new[3] = {16'h1, b0[15 : 0]};
                end

                15: begin
                  c_new[0] = b3;
                  c_new[1] = b2;
                  c_new[2] = b1;
                  c_new[3] = {8'h1, b0[23 : 0]};
                end
              endcase // case (blocklen[3 : 0])
              c_new[4] = 32'h0;
              c_we     = 1'h1;
            end
          else
            begin
              // Handling of full blocks.
              c_new[0] = b3;
              c_new[1] = b2;
              c_new[2] = b1;
              c_new[3] = b0;
              c_new[4] = 32'h1;
              c_we     = 1'h1;
            end
        end


      if (state_update)
        begin
          for (i = 0 ; i < 5 ; i = i + 1)
            h_new[i] = pblock_h_new[i];
          h_we = 1'h1;
        end


      if (mac_update)
        begin
          mac_new[3] = le(hres0);
          mac_new[2] = le(hres1);
          mac_new[1] = le(hres2);
          mac_new[0] = le(hres3);
          mac_we     = 1'h1;
        end
    end // poly1305_core_logic


  //----------------------------------------------------------------
  // poly1305_core_ctrl
  //----------------------------------------------------------------
  always @*
    begin : poly1305_core_ctrl
      state_init             = 1'h0;
      load_block             = 1'h0;
      state_update           = 1'h0;
      pblock_start           = 1'h0;
      final_start            = 1'h0;
      mac_update             = 1'h0;
      ready_new              = 1'h0;
      ready_we               = 1'h0;
      poly1305_core_ctrl_new = CTRL_IDLE;
      poly1305_core_ctrl_we  = 1'h0;


      case (poly1305_core_ctrl_reg)
        CTRL_IDLE:
          begin
            if (init)
              begin
                state_init             = 1'h1;
                ready_new              = 1'h0;
                ready_we               = 1'h1;
                poly1305_core_ctrl_new = CTRL_READY;
                poly1305_core_ctrl_we  = 1'h1;
              end

            if (next)
              begin
                load_block             = 1'h1;
                ready_new              = 1'h0;
                ready_we               = 1'h1;

                if (blocklen > 0)
                  begin
                    poly1305_core_ctrl_new = CTRL_NEXT;
                    poly1305_core_ctrl_we  = 1'h1;
                  end
                else
                  begin
                    poly1305_core_ctrl_new = CTRL_READY;
                    poly1305_core_ctrl_we  = 1'h1;
                  end
              end

            if (finish)
              begin
                final_start            = 1'h1;
                ready_new              = 1'h0;
                ready_we               = 1'h1;
                poly1305_core_ctrl_new = CTRL_FINAL;
                poly1305_core_ctrl_we  = 1'h1;
              end
          end


        CTRL_NEXT:
          begin
            pblock_start           = 1'h1;
            poly1305_core_ctrl_new = CTRL_NEXT_WAIT;
            poly1305_core_ctrl_we  = 1'h1;
          end


        CTRL_NEXT_WAIT:
          begin
            if (pblock_ready)
              begin
                state_update           = 1'h1;
                poly1305_core_ctrl_new = CTRL_READY;
                poly1305_core_ctrl_we  = 1'h1;
              end
          end


        CTRL_FINAL:
          begin
            if (final_ready)
              begin
                mac_update             = 1'h1;
                ready_new              = 1'h1;
                ready_we               = 1'h1;
                poly1305_core_ctrl_new = CTRL_IDLE;
                poly1305_core_ctrl_we  = 1'h1;
              end
          end


        CTRL_READY:
          begin
            ready_new              = 1'h1;
            ready_we               = 1'h1;
            poly1305_core_ctrl_new = CTRL_IDLE;
            poly1305_core_ctrl_we  = 1'h1;
          end

        default:
          begin
          end
      endcase // case (poly1305_core_ctrl_reg)
    end

endmodule // poly1305_core

//======================================================================
// EOF poly1305_core.v
//======================================================================
`undef WT_DCACHE
`undef DISABLE_TRACER
`undef SRAM_NO_INIT
`undef VERILATOR
// --- KẾT THÚC FILE: poly1305.preprocessed.v ---

// --- BẮT ĐẦU FILE: ed25519_sign.v ---
module ed25519_sign (
    input wire clk,
    input wire rst,

    input wire cs,
    input wire we,

    input wire [7:0] address,
    input wire [31:0] write_data,
    output wire [31:0] read_data,
    output wire error
);

/*---------------------------INTERNAL CONSTANTS-------------------------------*/

localparam ADDR_NAME0       = 8'h00;
localparam ADDR_NAME1       = 8'h01;
localparam ADDR_VERSION     = 8'h02;

localparam ADDR_CTRL        = 8'h08;
localparam CTRL_ENA_BIT     = 0;

localparam ADDR_STATUS      = 8'h09;
localparam STATUS_READY_BIT = 0;
localparam STATUS_DONE_BIT  = 1;

localparam ADDR_SECRET0     = 8'h10;
localparam ADDR_SECRET1     = 8'h11;
localparam ADDR_SECRET2     = 8'h12;
localparam ADDR_SECRET3     = 8'h13;
localparam ADDR_SECRET4     = 8'h14;
localparam ADDR_SECRET5     = 8'h15;
localparam ADDR_SECRET6     = 8'h16;
localparam ADDR_SECRET7     = 8'h17;

localparam ADDR_PUBLIC0     = 8'h20;
localparam ADDR_PUBLIC1     = 8'h21;
localparam ADDR_PUBLIC2     = 8'h22;
localparam ADDR_PUBLIC3     = 8'h23;
localparam ADDR_PUBLIC4     = 8'h24;
localparam ADDR_PUBLIC5     = 8'h25;
localparam ADDR_PUBLIC6     = 8'h26;
localparam ADDR_PUBLIC7     = 8'h27;

localparam ADDR_MESSAGE0    = 8'h30;
localparam ADDR_MESSAGE1    = 8'h31;
localparam ADDR_MESSAGE2    = 8'h32;
localparam ADDR_MESSAGE3    = 8'h33;
localparam ADDR_MESSAGE4    = 8'h34;
localparam ADDR_MESSAGE5    = 8'h35;
localparam ADDR_MESSAGE6    = 8'h36;
localparam ADDR_MESSAGE7    = 8'h37;

localparam ADDR_R0          = 8'h40;
localparam ADDR_R1          = 8'h41;
localparam ADDR_R2          = 8'h42;
localparam ADDR_R3          = 8'h43;
localparam ADDR_R4          = 8'h44;
localparam ADDR_R5          = 8'h45;
localparam ADDR_R6          = 8'h46;
localparam ADDR_R7          = 8'h47;

localparam ADDR_S0          = 8'h50;
localparam ADDR_S1          = 8'h51;
localparam ADDR_S2          = 8'h52;
localparam ADDR_S3          = 8'h53;
localparam ADDR_S4          = 8'h54;
localparam ADDR_S5          = 8'h55;
localparam ADDR_S6          = 8'h56;
localparam ADDR_S7          = 8'h57;

localparam CORE_NAME0       = 32'h65643235; // "ed25"
localparam CORE_NAME1       = 32'h35313900; // "519 "
localparam CORE_VERSION     = 32'h31333337; // "1337"

/*------------------------------------REGS------------------------------------*/

reg ena_reg;
reg ena_new;
reg ena_we;
reg ena_set;

reg done_reg;
reg done_new;
reg done_we;

reg [31:0] secret_0_reg;
reg secret_0_we;
reg [31:0] secret_1_reg;
reg secret_1_we;
reg [31:0] secret_2_reg;
reg secret_2_we;
reg [31:0] secret_3_reg;
reg secret_3_we;
reg [31:0] secret_4_reg;
reg secret_4_we;
reg [31:0] secret_5_reg;
reg secret_5_we;
reg [31:0] secret_6_reg;
reg secret_6_we;
reg [31:0] secret_7_reg;
reg secret_7_we;

reg [31:0] public_0_reg;
reg public_0_we;
reg [31:0] public_1_reg;
reg public_1_we;
reg [31:0] public_2_reg;
reg public_2_we;
reg [31:0] public_3_reg;
reg public_3_we;
reg [31:0] public_4_reg;
reg public_4_we;
reg [31:0] public_5_reg;
reg public_5_we;
reg [31:0] public_6_reg;
reg public_6_we;
reg [31:0] public_7_reg;
reg public_7_we;

reg [31:0] message_0_reg;
reg message_0_we;
reg [31:0] message_1_reg;
reg message_1_we;
reg [31:0] message_2_reg;
reg message_2_we;
reg [31:0] message_3_reg;
reg message_3_we;
reg [31:0] message_4_reg;
reg message_4_we;
reg [31:0] message_5_reg;
reg message_5_we;
reg [31:0] message_6_reg;
reg message_6_we;
reg [31:0] message_7_reg;
reg message_7_we;

reg r_we;
reg [255:0] r_reg;
reg [255:0] r_new;

reg s_we;
reg [255:0] s_reg;
reg [255:0] s_new;

reg ready_reg;
reg [31:0] tmp_read_data;
reg tmp_error;
/*-----------------------------------WIRES------------------------------------*/

wire core_ena;
wire core_ready;
wire core_comp_done;
wire [255:0] core_sk;
wire [255:0] core_pk;
wire [255:0] core_M;
wire [255:0] core_S;
wire [255:0] core_R;

/*---------------------------------CONNECTIVITY-------------------------------*/

assign read_data = tmp_read_data;

assign error     = tmp_error;

assign core_sk   = {secret_7_reg, secret_6_reg, secret_5_reg, secret_4_reg,
                    secret_3_reg, secret_2_reg, secret_1_reg, secret_0_reg};

assign core_pk   = {public_7_reg, public_6_reg, public_5_reg, public_4_reg,
                    public_3_reg, public_2_reg, public_1_reg, public_0_reg};

assign core_M    = {message_7_reg, message_6_reg, message_5_reg, message_4_reg,
                    message_3_reg, message_2_reg, message_1_reg, message_0_reg};

assign core_ena  = ena_reg;


/*--------------------------------COMPONENTS----------------------------------*/

sign_core core (
    .clk(clk),
    .rst(rst),
    .core_ena(core_ena),
    .core_ready(core_ready),
    .core_comp_done(core_comp_done),
    .core_sk(core_sk),
    .core_pk(core_pk),
    .core_M(core_M),
    .core_S(core_S),
    .core_R(core_R)
    );

/*---------------------------------REG UPDATE---------------------------------*/

always @(posedge clk) begin
    if (rst) begin
        ena_reg       <= 1'b0;
        secret_0_reg  <= 32'h00000000;
        secret_1_reg  <= 32'h00000000;
        secret_2_reg  <= 32'h00000000;
        secret_3_reg  <= 32'h00000000;
        secret_4_reg  <= 32'h00000000;
        secret_5_reg  <= 32'h00000000;
        secret_6_reg  <= 32'h00000000;
        secret_7_reg  <= 32'h00000000;
        public_0_reg  <= 32'h00000000;
        public_1_reg  <= 32'h00000000;
        public_2_reg  <= 32'h00000000;
        public_3_reg  <= 32'h00000000;
        public_4_reg  <= 32'h00000000;
        public_5_reg  <= 32'h00000000;
        public_6_reg  <= 32'h00000000;
        public_7_reg  <= 32'h00000000;
        message_0_reg <= 32'h00000000;
        message_1_reg <= 32'h00000000;
        message_2_reg <= 32'h00000000;
        message_3_reg <= 32'h00000000;
        message_4_reg <= 32'h00000000;
        message_5_reg <= 32'h00000000;
        message_6_reg <= 32'h00000000;
        message_7_reg <= 32'h00000000;
        s_reg         <= 256'b0;
        r_reg         <= 256'b0;
        ready_reg     <= 1'b0;
        done_reg      <= 1'b0;
    end

    else begin
        ready_reg <= core_ready;

        if (ena_we)
            ena_reg      <= ena_new;
        if (secret_0_we)
            secret_0_reg <= write_data;
        if (secret_1_we)
            secret_1_reg <= write_data;
        if (secret_2_we)
            secret_2_reg <= write_data;
        if (secret_3_we)
            secret_3_reg <= write_data;
        if (secret_4_we)
            secret_4_reg <= write_data;
        if (secret_5_we)
            secret_5_reg <= write_data;
        if (secret_6_we)
            secret_6_reg <= write_data;
        if (secret_7_we)
            secret_7_reg <= write_data;

        if (public_0_we)
            public_0_reg <= write_data;
        if (public_1_we)
            public_1_reg <= write_data;
        if (public_2_we)
            public_2_reg <= write_data;
        if (public_3_we)
            public_3_reg <= write_data;
        if (public_4_we)
            public_4_reg <= write_data;
        if (public_5_we)
            public_5_reg <= write_data;
        if (public_6_we)
            public_6_reg <= write_data;
        if (public_7_we)
            public_7_reg <= write_data;

        if (message_0_we)
            message_0_reg <= write_data;
        if (message_1_we)
            message_1_reg <= write_data;
        if (message_2_we)
            message_2_reg <= write_data;
        if (message_3_we)
            message_3_reg <= write_data;
        if (message_4_we)
            message_4_reg <= write_data;
        if (message_5_we)
            message_5_reg <= write_data;
        if (message_6_we)
            message_6_reg <= write_data;
        if (message_7_we)
            message_7_reg <= write_data;

        if (done_we)
            done_reg <= done_new;
        if (r_we)
            r_reg <= r_new;
        if (s_we)
            s_reg <= s_new;
    end
end

always @* begin
    ena_new = 1'b0;
    ena_we = 1'b0;

    r_we = 1'b0;
    s_we = 1'b0;
    done_we = 1'b0;
    s_new = 256'b0;
    r_new = 256'b0;
    done_new = 1'b0;

    if (ena_set & ready_reg) begin
        ena_new = 1'b1;
        ena_we  = 1'b1;

        /* Clear these registers on new computation start */
        r_we = 1'b1;
        s_we = 1'b1;
        done_we = 1'b1;
    end
    else if (ena_reg) begin
        ena_new = 1'b0;
        ena_we  = 1'b1;
    end

    if (core_comp_done) begin
        /* Save results */
        r_we = 1'b1;
        s_we = 1'b1;
        done_we = 1'b1;
        r_new = core_R;
        s_new = core_S;
        done_new = 1'b1;
    end
end

always @* begin
    ena_set      = 1'b0;

    secret_0_we   = 1'b0;
    secret_1_we   = 1'b0;
    secret_2_we   = 1'b0;
    secret_3_we   = 1'b0;
    secret_4_we   = 1'b0;
    secret_5_we   = 1'b0;
    secret_6_we   = 1'b0;
    secret_7_we   = 1'b0;
    public_0_we   = 1'b0;
    public_1_we   = 1'b0;
    public_2_we   = 1'b0;
    public_3_we   = 1'b0;
    public_4_we   = 1'b0;
    public_5_we   = 1'b0;
    public_6_we   = 1'b0;
    public_7_we   = 1'b0;
    message_0_we  = 1'b0;
    message_1_we  = 1'b0;
    message_2_we  = 1'b0;
    message_3_we  = 1'b0;
    message_4_we  = 1'b0;
    message_5_we  = 1'b0;
    message_6_we  = 1'b0;
    message_7_we  = 1'b0;
    tmp_read_data = 32'h00000000;
    tmp_error     = 1'b0;

    if (cs) begin
        if (we) begin
            /* Enable write */
            case (address)
                ADDR_CTRL:
                    ena_set     = write_data[CTRL_ENA_BIT];
                ADDR_SECRET0:
                    secret_0_we = 1'b1;
                ADDR_SECRET1:
                    secret_1_we = 1'b1;
                ADDR_SECRET2:
                    secret_2_we = 1'b1;
                ADDR_SECRET3:
                    secret_3_we = 1'b1;
                ADDR_SECRET4:
                    secret_4_we = 1'b1;
                ADDR_SECRET5:
                    secret_5_we = 1'b1;
                ADDR_SECRET6:
                    secret_6_we = 1'b1;
                ADDR_SECRET7:
                    secret_7_we = 1'b1;

                ADDR_PUBLIC0:
                    public_0_we = 1'b1;
                ADDR_PUBLIC1:
                    public_1_we = 1'b1;
                ADDR_PUBLIC2:
                    public_2_we = 1'b1;
                ADDR_PUBLIC3:
                    public_3_we = 1'b1;
                ADDR_PUBLIC4:
                    public_4_we = 1'b1;
                ADDR_PUBLIC5:
                    public_5_we = 1'b1;
                ADDR_PUBLIC6:
                    public_6_we = 1'b1;
                ADDR_PUBLIC7:
                    public_7_we = 1'b1;

                ADDR_MESSAGE0:
                    message_0_we = 1'b1;
                ADDR_MESSAGE1:
                    message_1_we = 1'b1;
                ADDR_MESSAGE2:
                    message_2_we = 1'b1;
                ADDR_MESSAGE3:
                    message_3_we = 1'b1;
                ADDR_MESSAGE4:
                    message_4_we = 1'b1;
                ADDR_MESSAGE5:
                    message_5_we = 1'b1;
                ADDR_MESSAGE6:
                    message_6_we = 1'b1;
                ADDR_MESSAGE7:
                    message_7_we = 1'b1;
                default:
                    tmp_error = 1'b1;
            endcase
        end
        else begin
            /* Read operations */
            case (address)
                ADDR_NAME0:
                    tmp_read_data = CORE_NAME0;
                ADDR_NAME1:
                    tmp_read_data = CORE_NAME1;
                ADDR_VERSION:
                    tmp_read_data = CORE_VERSION;
                ADDR_CTRL:
                    tmp_read_data = {31'b0, ena_reg};
                ADDR_STATUS:
                    tmp_read_data = {30'b0, done_reg, ready_reg};
                ADDR_R0:
                    tmp_read_data = r_reg[31:0];
                ADDR_R1:
                    tmp_read_data = r_reg[63:32];
                ADDR_R2:
                    tmp_read_data = r_reg[95:64];
                ADDR_R3:
                    tmp_read_data = r_reg[127:96];
                ADDR_R4:
                    tmp_read_data = r_reg[159:128];
                ADDR_R5:
                    tmp_read_data = r_reg[191:160];
                ADDR_R6:
                    tmp_read_data = r_reg[223:192];
                ADDR_R7:
                    tmp_read_data = r_reg[255:224];
                ADDR_S0:
                    tmp_read_data = s_reg[31:0];
                ADDR_S1:
                    tmp_read_data = s_reg[63:32];
                ADDR_S2:
                    tmp_read_data = s_reg[95:64];
                ADDR_S3:
                    tmp_read_data = s_reg[127:96];
                ADDR_S4:
                    tmp_read_data = s_reg[159:128];
                ADDR_S5:
                    tmp_read_data = s_reg[191:160];
                ADDR_S6:
                    tmp_read_data = s_reg[223:192];
                ADDR_S7:
                    tmp_read_data = s_reg[255:224];
                default:
                    tmp_error = 1'b1;
            endcase
        end
    end
end

endmodule
// --- KẾT THÚC FILE: ed25519_sign.v ---

// --- BẮT ĐẦU FILE: ascon.v ---
`timescale 1ns / 1ps

module ascon
  #(//Memory parameters
    parameter depth = 1024,
    parameter aw    = $clog2(depth),  
    parameter CCW = 32,
    parameter CCSW = 32
    )
   (input wire 		   i_clk,
    input wire 		   i_rst,
    input wire [31:0]  i_data,
    input wire         i_write_data,
    input wire         i_start,
    output wire        in_fifo_full,
    output wire [31:0] out_fifo_data,
    output wire        out_fifo_empty,
    output wire        o_done,
    output wire        tag_valid,
    input wire         out_fifo_rd_en,
    input wire         input_finish
);
  wire [31:0] ascon_wr_data;
  wire [31:0] fifo2Ascon_data;
  wire [5:0] fifo_in_counter;
  wire rd_en;
  wire in_fifo_empty;
  wire o_write_data;

    fifo fifo_in(
    .clk(i_clk),
    .rst(i_rst),
    .buf_in(i_data),
    .buf_out(fifo2Ascon_data),
    .wr_en(i_write_data),
    .rd_en(rd_en),
    .buf_empty(in_fifo_empty),
    .buf_full(in_fifo_full),
    .fifo_counter(fifo_in_counter)
    );
    
    
    ascon_core ascon_inst(
    .i_wb_clk(i_clk),
    .i_wb_rst(i_rst),
    .i_wb_dat(fifo2Ascon_data),
    .o_rd_en(rd_en),
    .o_done(o_done),
    .tag_valid(tag_valid),
    .i_start(i_start),
    .in_fifo_empty(in_fifo_empty),
    .o_wr_en(o_write_data),
    .o_wr_data(ascon_wr_data),
    .fifo_in_counter(fifo_in_counter),
    .input_finish(input_finish)
    );
    
     fifo fifo_out(
    .clk(i_clk),
    .rst(i_rst),
    .buf_in(ascon_wr_data),
    .buf_out(out_fifo_data),
    .wr_en(o_write_data),
    .rd_en(out_fifo_rd_en),
    .buf_empty(out_fifo_empty),
    .buf_full(),
    .fifo_counter()
    );
    
endmodule


`timescale 1ns / 1ps

module ascon_core
#(//Memory parameters
    parameter depth = 1024,
    parameter aw    = $clog2(depth),  
    parameter CCW = 32,
    parameter CCSW = 32,

  // Operation types
    parameter [4:0] OP_DO_ENC = 5'h0,
    parameter [4:0] OP_DO_DEC = 5'h1,
    parameter [4:0] OP_DO_HASH = 5'h2,
    parameter [4:0] OP_LD_KEY = 5'h3,
    parameter [4:0] OP_LD_NONCE = 5'h4,
    parameter [4:0] OP_LD_MS = 5'h5,
    parameter [4:0] OP_LD_PT = 5'h6,
    parameter [4:0] OP_LD_CT = 5'h7,
    parameter [4:0] OP_LD_TAG = 5'h8

    )(
    input wire 		   i_wb_clk,
    input wire 		   i_wb_rst,
    input wire [31:0]  i_wb_dat,
    output reg          o_rd_en,
    output reg          o_wr_en,
    output reg          tag_valid,
    output reg          o_done,
    input wire 		    i_start,
    input wire 		    in_fifo_empty,
    output reg [31:0]   o_wr_data,
    input wire [5:0]    fifo_in_counter,
    input wire          input_finish
    );
    
    reg [23:0] tb_word_cnt;
    reg [3:0] op;
    reg decryption;
    reg hash;
    reg [3:0] rcon;
    reg [2:0] byte_count;
    
    reg [63:0] x0_in;
    reg [63:0] x1_in;
    reg [63:0] x2_in;
    reg [63:0] x3_in;
    reg [63:0] x4_in;
   
    wire [63:0] x0_out;
    wire [63:0] x1_out;
    wire [63:0] x2_out;
    wire [63:0] x3_out;
    wire [63:0] x4_out;
       
    reg  [127:0] ascon_key;
    reg  [3:0] fsm_state;
  
    //managing reading ascon key
    // Write key when both valid and ready are high
    //shift 32 bits each cycle, 128 in total
    always @(posedge i_wb_clk) begin
        if (i_wb_rst) begin
            ascon_key <= 128'b0;
        end else if (op == OP_LD_KEY & tb_word_cnt > 1)
                ascon_key <= {ascon_key[95:0], i_wb_dat};
           else ascon_key <= ascon_key;
    end
    
    always@(posedge i_wb_clk) begin
        if(i_wb_rst) begin
            o_rd_en <= 1'b0;
            fsm_state <= 4'b0000;
            tb_word_cnt <= 24'b0;
            decryption <= 1'b0;
            hash <= 1'b0;
            op <= 4'b0;
            byte_count <= 3'b0;
        end
        else begin
        case(fsm_state)
        //idle state, wait for start signal
        4'b0000: begin
            o_rd_en <= 1'b0;
            decryption <= 1'b0;
            hash <= 1'b0;
            op <= 4'b0;
            tb_word_cnt <= 24'b0;
            byte_count <= 3'b0;
            if(i_start) begin
                fsm_state <= 4'b0001;
                //o_rd_en <= 1'b1;
            end
            else begin
                fsm_state <= 4'b0000;
            end
        end
        //buffer state, the memory need 2 cycles to respond
        4'b0001:begin
            if(!in_fifo_empty) begin
                fsm_state <= 4'b0010;
                o_rd_en <= 1'b1;
            end
        end
        //opcode for key
        4'b0010:begin
            tb_word_cnt <= (i_wb_dat[23:0] + 3) / 4 + 1;
            op <= i_wb_dat[31:28];
            fsm_state <= 4'b0011;
        end
        //load key or nonce state
        4'b0011: begin
            if(tb_word_cnt > 1) begin 
                fsm_state <= 4'b0011;
                tb_word_cnt <= tb_word_cnt - 1;
            end
            else begin
                tb_word_cnt <= (i_wb_dat[23:0] + 3) / 4 + 1;
                op <= i_wb_dat[31:28];
                if(op == OP_LD_KEY) begin
                    fsm_state <= 4'b0100;
                    o_rd_en <= 1'b1;
                end
                else if(op == OP_LD_NONCE) begin
                    fsm_state <= 4'b0101;
                    o_rd_en <= 1'b0;
                end
                else if(op == OP_LD_MS) begin
                    if(fifo_in_counter < 1) fsm_state <= 4'd3;
                    else begin
                        fsm_state <= 4'd5;
                        o_rd_en <= 1'b1;
                    end
                end
                
            end
        end
        //loa
        4'b0100: begin
            if(tb_word_cnt < 2) begin
                tb_word_cnt <= (i_wb_dat[23:0] + 3) / 4 + 1;
                op <= i_wb_dat[31:28];
                decryption <= op[0];
                hash <= op[1];
                o_rd_en <= 1'b0;
                if(op == 2) fsm_state <= 4'd3;
            end 
            else begin
                tb_word_cnt <= tb_word_cnt;
                op <= op;
                if(op == OP_LD_TAG) fsm_state <= 4'd0;
                else if(hash) begin
                    if(fifo_in_counter < 2) begin
                        fsm_state <= 4'd4;
                        o_rd_en <= 1'b0;
                    end
                    else begin 
                        o_rd_en <= 1'b1;
                        fsm_state <= 4'd5;
                    end
                end
                else begin 
                    if(fifo_in_counter < 7) begin 
                        fsm_state <= 4'd4; 
                        o_rd_en <= 1'b0; 
                    end
                    else begin 
                        fsm_state <= 4'd3;
                        o_rd_en <= 1'b1;
                    end
                end
            end
        end
        4'b0101: begin
            o_rd_en <= 1'b0;
            if(rcon > 1) begin
                fsm_state <= 4'b0101;
            end
            else begin
                if(fifo_in_counter < 2) fsm_state <= 4'd5;
                else fsm_state <= 4'd6;
            end
        end
        4'b0110: begin
            if(op == OP_LD_PT || op == OP_LD_CT) fsm_state <= 4'd10;
            else begin
                fsm_state <= 4'd7;
                tb_word_cnt <= tb_word_cnt - 1;
                o_rd_en <= 1'b1;
            end
        end
        4'b0111: begin
            fsm_state <= 4'b1000;
            tb_word_cnt <= tb_word_cnt - 1;
            //o_rd_en <= 1'b1;
        end
        4'b1000: begin
            fsm_state <= 9;
            o_rd_en <= 1'b0;
        end
        4'd9: begin
            if(rcon > 1) begin
                fsm_state <= 4'b1001;
            end
            else if(tb_word_cnt == 1) begin
                if(hash) begin 
                    fsm_state <= 10;
                    tb_word_cnt <= 9;
                    o_rd_en <= 1'b0;
                end
                else if(fifo_in_counter < 4) 
                     fsm_state <= 9;
                else begin
                    fsm_state <= 10;
                    tb_word_cnt <= (i_wb_dat[23:0] + 3) / 4 + 1;
                    o_rd_en <= 1'b1;
                    op <= i_wb_dat[31:28];
                end
            end 
            else begin
                //if(hash & fifo_in_counter < 2) begin
                //    fsm_state <= 4'd7;
                //    o_rd_en <= 1'b1;
                //    tb_word_cnt <= tb_word_cnt - 1;
                //end
                if((fifo_in_counter < 4 & !hash) | (hash & fifo_in_counter < 2)) fsm_state <= 4'd9;
                else begin
                    fsm_state <= 4'b0111;
                    o_rd_en <= 1'b1;
                    tb_word_cnt <= tb_word_cnt - 1;
                end
            end
        end
        4'd10: begin
            fsm_state <= 4'd11;
            tb_word_cnt <= tb_word_cnt - 1;
            if(!hash) o_rd_en <= 1'b1;
        end
        4'd11: begin
            fsm_state <= 4'd12;
            if(!hash) o_rd_en <= 1'b1;
        end
        4'd12: begin
            fsm_state <= 4'd13;
            tb_word_cnt <= tb_word_cnt - 1;
            o_rd_en <= 1'b0;
            
        end
        4'd13: begin
            if(rcon > 1) begin
                fsm_state <= 4'd13;
            end
            else if(tb_word_cnt == 1) begin
                if(input_finish) fsm_state <= 4'd0;
                else if(fifo_in_counter < 6) fsm_state <= 4'd13;
                else fsm_state <= 4'd14;
            end 
            else begin
                if(hash) begin
                    fsm_state <= 4'd11;
                    tb_word_cnt <= tb_word_cnt - 1;
                end
                else if(fifo_in_counter < 3) fsm_state <= 4'd13;
                else begin 
                    fsm_state <= 4'd11;
                    tb_word_cnt <= tb_word_cnt - 1;
                    o_rd_en <= 1'b1;
                end
            end
        end
        4'd14: begin
            if(!hash) fsm_state <= 4'd15;
            else fsm_state <= 4'd0;
            byte_count <= 6;
            if(decryption) o_rd_en <= 1'b1;
            else tb_word_cnt <= tb_word_cnt - 1;
        end
        4'd15: begin            
            if(byte_count > 1) begin
                fsm_state <= 4'd15;
                byte_count <= byte_count - 1;
                if(byte_count == 2 ) o_rd_en <= 1'b1;
            end
            else begin
                //if(fifo_in_counter < 7) fsm_state <= 4'd15;
                //else begin
                    fsm_state <= 4'd4;
                    o_rd_en <= 1'b1;
                    tb_word_cnt <= (i_wb_dat[23:0] + 3) / 4 + 1;
                    op <= i_wb_dat[31:28];
                //end
            end
        end
        endcase
        end
    end
    
    always @(posedge i_wb_clk) begin
        if (i_wb_rst) begin
            x0_in <= 64'b0;
            x1_in <= 64'b0;
            x2_in <= 64'b0;
            x3_in <= 64'b0;
            x4_in <= 64'b0;
        end else if (op == OP_LD_NONCE & tb_word_cnt > 1) begin
                x0_in <= 64'h80400c0600000000;
                x1_in <= ascon_key[127:64];
                x2_in <= ascon_key[63:0];
                x3_in <= {x3_in[31:0], x4_in[63:32]};
                x4_in <= {x4_in[31:0], i_wb_dat};
            end
            else if (op == OP_LD_MS & fsm_state == 3) begin
                x0_in <= 64'h00400c0000000100;
                x1_in <= 64'b0;
                x2_in <= 64'b0;
                x3_in <= 64'b0;
                x4_in <= 64'b0;
            end
        else if((fsm_state == 5 | fsm_state == 9 | fsm_state == 13) & rcon > 0) begin
                x0_in <= x0_out;
                x1_in <= x1_out;
                x2_in <= x2_out;
                x3_in <= x3_out;
                x4_in <= x4_out;
            end
        else if((fsm_state == 6 | fsm_state == 14) & !hash) begin
                x3_in <= x3_in ^ ascon_key[127:64];
                x4_in <= x4_in ^ ascon_key[63:0]; 
        end
        else if(fsm_state == 7 | (fsm_state == 11 & !decryption & !hash)) begin
                x0_in[63:32] <= x0_in[63:32] ^ i_wb_dat;
        end
        else if(fsm_state == 11 & decryption & !hash) begin
                x0_in[63:32] <= i_wb_dat;
        end
        else if((fsm_state == 8) | (fsm_state == 12 & tb_word_cnt > 2 & !decryption & !hash)) begin
                x0_in[31:0] <= x0_in[31:0] ^ i_wb_dat;
        end
        else if(fsm_state == 12 & tb_word_cnt > 2 & decryption & !hash) begin
                x0_in[31:0] <= i_wb_dat;
        end
        else if(fsm_state == 10 & !hash) begin
                x4_in[0] <= x4_in[0] ^ 1'b1;
        end
        else if(fsm_state == 12 & tb_word_cnt == 2 & !decryption & !hash) begin
                x1_in <= x1_in ^ ascon_key[127:64];
                x2_in <= x2_in ^ ascon_key[63:0]; 
                x0_in[31:0] <= x0_in[31:0] ^ i_wb_dat;
        end
        else if(fsm_state == 12 & tb_word_cnt == 2 & decryption & !hash) begin
                x1_in <= x1_in ^ ascon_key[127:64];
                x2_in <= x2_in ^ ascon_key[63:0]; 
                x0_in[31:0] <= i_wb_dat;
        end
    end
    
    always @(posedge i_wb_clk) begin
        if(i_wb_rst) rcon <= 4'b0;
        else if( (fsm_state == 3 & op == OP_LD_NONCE & tb_word_cnt == 1) | (fsm_state == 12 & tb_word_cnt == 2) | (fsm_state == 3 & op == OP_LD_MS & tb_word_cnt == 1) | ((fsm_state == 8 | fsm_state == 12) & hash)) rcon <= 4'hC;
        else if((fsm_state == 8 | fsm_state == 12) & !hash) rcon <= 4'h6;
        else if((fsm_state == 5 | fsm_state == 9 | fsm_state == 13) & rcon > 4'b0)  rcon <= rcon - 4'b1;
        else rcon <= 4'b0;
    end
    
    always @(posedge i_wb_clk) begin
        if(i_wb_rst) o_done <= 1'b0;
        else if(fsm_state == 4 & op == OP_LD_TAG)  o_done <= 1'b1;
    end
    
    always @(posedge i_wb_clk) begin
        if (i_wb_rst) begin
            o_wr_data <= 32'b0;
            o_wr_en <= 1'b0;
        end
        else if(fsm_state == 11) begin
            if(!hash) o_wr_data <= x0_in[63:32] ^ i_wb_dat;
            else o_wr_data <= x0_in[63:32];
            o_wr_en <= 1'b1;
        end
        else if(fsm_state == 12) begin
            if(!hash) o_wr_data <= x0_in[31:0] ^ i_wb_dat;
            else o_wr_data <= x0_in[31:0];
            o_wr_en <= 1'b1;
        end
        else if(fsm_state == 15 & byte_count == 6) begin
            o_wr_data <= x3_in[63:32];
            o_wr_en <= 1'b1;
        end
        else if(fsm_state == 15 & byte_count == 5) begin
            o_wr_data <= x3_in[31:0];
            o_wr_en <= 1'b1;
            if(o_wr_data == i_wb_dat) tag_valid <= 1'b1;
        end
        else if(fsm_state == 15 & byte_count == 4) begin
            o_wr_data <= x4_in[63:32];
            o_wr_en <= 1'b1;
            if(o_wr_data == i_wb_dat) tag_valid <= 1'b1;
        end
        else if(fsm_state == 15 & byte_count == 3) begin
            o_wr_data <= x4_in[31:0];
            o_wr_en <= 1'b1;
            if(o_wr_data == i_wb_dat) tag_valid <= 1'b1;
        end
        else if(fsm_state == 15 & byte_count == 2) begin
                o_wr_en <= 1'b0;
                if(o_wr_data == i_wb_dat) tag_valid <= 1'b1;
        end
        else begin
            o_wr_data <= 32'b0;
            o_wr_en <= 1'b0;
            tag_valid <= 1'b0;
        end
    end 
    asconp asconp_inst(
                        .rcon(rcon),
                        .x0_in(x0_in),
                        .x1_in(x1_in),
                        .x2_in(x2_in),
                        .x3_in(x3_in),
                        .x4_in(x4_in),
                        .x0_out(x0_out),
                        .x1_out(x1_out),
                        .x2_out(x2_out),
                        .x3_out(x3_out),
                        .x4_out(x4_out)
    );

endmodule


`timescale 1ns / 1ps

module asconp
    #(                  parameter                   STATE_WORDS     = 64,
                        parameter                   BYTE_WIDTH      = 8,
                        parameter   [3:0]           ROUND_16        = 4'hF,   
                        parameter   [3:0]           ROUND_12        = 4'hC   
    )
    (
                        //input       [319:0]         state_in,
                        input       [3:0]           rcon,
                        //output      [319:0]         state_out,
                        output wire      [63:0]          x0_out,    
                        output wire      [63:0]          x1_out,    
                        output wire      [63:0]          x2_out,    
                        output wire      [63:0]          x3_out,    
                        output wire      [63:0]          x4_out,    
                        input wire       [63:0]          x0_in,    
                        input wire       [63:0]          x1_in,    
                        input wire       [63:0]          x2_in,    
                        input wire       [63:0]          x3_in,    
                        input wire      [63:0]          x4_in    
    );
    
//wire [STATE_WORDS - 1:0] x0, x1, x2, x3, x4;
wire [STATE_WORDS - 1:0] x0_r, x1_r, x2_r, x3_r, x4_r;
wire [STATE_WORDS - 1:0] t0, t1;
wire [STATE_WORDS - 1:0] x0_first, x1_first, x2_first, x3_first, x4_first;
wire [STATE_WORDS - 1:0] x0_second, x1_second, x2_second, x3_second, x4_second;
wire [STATE_WORDS - 1:0] x0_third, x1_third, x2_third, x3_third, x4_third;
//wire [STATE_WORDS - 1:0] x0_rotated, x1_rotated, x2_rotated, x3_rotated, x4_rotated;
//wire [STATE_WORDS - 1:0] x0_out, x1_out, x2_out, x3_out, x4_out;
wire [BYTE_WIDTH - 1:0] round_constant;
wire [BYTE_WIDTH - 1:0] x2_constant;
wire [55: 0] x2_no_constant;
wire [3:0]               t2;

assign x0_r = x0_in;
assign x1_r = x1_in;
assign x2_r = x2_in;
assign x3_r = x3_in;
assign x4_r = x4_in;
//Linear operation and addition of round constant

assign x0_first = x0_r ^ x4_r;

assign x1_first = x1_r;

assign t2 = ROUND_12 - rcon;
assign round_constant [7:4] = ROUND_16 - t2;
assign round_constant [3:0] = t2;
assign x2_constant = x2_r[7:0] ^ x1_r[7:0] ^ round_constant;
assign x2_no_constant  = x2_r[63:8] ^ x1_r[63:8];
assign x2_first = {x2_no_constant, x2_constant};

assign x3_first = x3_r;

assign x4_first = x4_r ^ x3_r;

//Nonlinear operation
assign t0 = x0_first;
assign t1 = x1_first;
assign x0_second = x0_first ^ ((~x1_first) & x2_first);
assign x1_second = x1_first ^ ((~x2_first) & x3_first);
assign x2_second = x2_first ^ ((~x3_first) & x4_first);
assign x3_second = x3_first ^ ((~x4_first) & x0_first);
assign x4_second = x4_first ^ ((~t0) & t1);

//Linear operation
assign x0_third = x0_second ^ x4_second;
assign x1_third = x1_second ^ x0_second;
assign x2_third = ~x2_second;
assign x3_third = x2_second ^ x3_second;
assign x4_third = x4_second;

//Lane rotation
/*
assign x0_rotated = x0_third ^ {x0_third[18:0], x0_third[63:19]} ^ {x0_third[27:0], x0_third[63:28]}; 
assign x1_rotated = x1_third ^ {x1_third[60:0], x1_third[63:61]} ^ {x1_third[38:0], x1_third[63:39]}; 
assign x2_rotated = x2_third ^ {x2_third[0:0],  x2_third[63:1]}  ^ {x2_third[5:0],  x2_third[63:6]}; 
assign x3_rotated = x3_third ^ {x3_third[9:0],  x3_third[63:10]} ^ {x3_third[16:0], x3_third[63:17]}; 
assign x4_rotated = x4_third ^ {x4_third[6:0],  x4_third[63:7]}  ^ {x4_third[40:0], x4_third[63:41]}; 
*/

assign x0_out = x0_third ^ {x0_third[18:0], x0_third[63:19]} ^ {x0_third[27:0], x0_third[63:28]}; 
assign x1_out = x1_third ^ {x1_third[60:0], x1_third[63:61]} ^ {x1_third[38:0], x1_third[63:39]}; 
assign x2_out = x2_third ^ {x2_third[0:0],  x2_third[63:1]}  ^ {x2_third[5:0],  x2_third[63:6]}; 
assign x3_out = x3_third ^ {x3_third[9:0],  x3_third[63:10]} ^ {x3_third[16:0], x3_third[63:17]}; 
assign x4_out = x4_third ^ {x4_third[6:0],  x4_third[63:7]}  ^ {x4_third[40:0], x4_third[63:41]}; 

//Map 5 x 64-bit lanes to 320 bit vector output

//assign state_out [STATE_WORDS -1 + 4 * STATE_WORDS : 4 * STATE_WORDS] = x0_out;
//assign state_out [STATE_WORDS -1 + 3 * STATE_WORDS : 3 * STATE_WORDS] = x1_out;
//assign state_out [STATE_WORDS -1 + 2 * STATE_WORDS : 2 * STATE_WORDS] = x2_out;
//assign state_out [STATE_WORDS -1 + 1 * STATE_WORDS : 1 * STATE_WORDS] = x3_out;
//assign state_out [STATE_WORDS -1 + 0 * STATE_WORDS : 0 * STATE_WORDS] = x4_out;


endmodule

`timescale 1ns / 1ps
